from pathlib import Path
import base64,hashlib,json,subprocess,zipfile
W=Path('/kaggle/working/hp_round14');R=Path('/root/r14_code_v2');assert not R.exists();R.mkdir()
p=W/'sources_v2.zip.dat';assert hashlib.sha256(p.read_bytes()).hexdigest()=='d0a4c8503cb10b975c4feb3eb4d9b2c2d8cafa8774d7ef8e77fd4c34c3a06511'
with zipfile.ZipFile(p) as z:
    for r in json.loads(z.read('source_manifest.json')):
        p=(R/r['path']).resolve();assert p.is_relative_to(R)
        raw=z.read(r['path']);assert len(raw)==r['bytes'] and hashlib.sha256(raw).hexdigest()==r['sha256']
        p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(raw)
Path('/root/r14_preflight_v2.py').write_bytes(base64.b64decode(''))
Path('/root/r14_dispatch_v2.py').write_bytes(base64.b64decode(''))
p=subprocess.Popen(['python','/root/r14_preflight_v2.py'],stdin=subprocess.DEVNULL,stdout=(W/'preflight_v2.log').open('ab'),stderr=subprocess.STDOUT,start_new_session=True)
print(json.dumps({'preflight_pid':p.pid}))